pub async fn retrieve_context(db: &Surreal<Db>, query_text: &str, embedder: &dyn embedder::TextEmbedder, abstract_mode: bool, skeleton_mode: bool) -> Result<String> {
    let query_vec = embedder.embed(query_text).await.unwrap_or_else(|_| vec![0.1; 768]);

    // Snippet field is chosen from a fixed allowlist â€” safe to interpolate via format!.
    // The user-controlled query text is passed through .bind() and must never touch
    // the SQL string directly, otherwise BM25 operators and quoting become an
    // injection surface that naive escaping cannot fully neutralize.
    let snippet_field = if skeleton_mode { "skeleton_snippet" } else { "code_snippet" };

    // Pull extra candidates so the in-Rust diversity rerank has something to
    // trade off. HNSW recall of 20 is cheap on a local index; the hard cap of
    // TOP_K on the final projection keeps context size bounded regardless of
    // how many rows BM25 matches.
    let sql = format!("
        LET $vec_res = SELECT id, vector::distance::knn() AS distance FROM entity WHERE embedding <|20, 80|> $q_vec;
        LET $fts_code = SELECT id, search::score(1) AS s FROM entity WHERE code_snippet @1@ $q_text ORDER BY s DESC LIMIT 20;
        LET $fts_name = SELECT id, search::score(2) AS s FROM entity WHERE name @2@ $q_text ORDER BY s DESC LIMIT 20;
        LET $fts_path = SELECT id, search::score(3) AS s FROM entity WHERE file_path @3@ $q_text ORDER BY s DESC LIMIT 20;
        LET $fused = search::rrf([$vec_res, $fts_code, $fts_name, $fts_path], 12, 60);

        SELECT
            name,
            {snippet_field} AS code_snippet,
            file_path,
            ->relates_to->entity.name AS relates_names,
            ->relates_to->entity.{snippet_field} AS relates_snippets,
            ->calls->entity.name AS calls_names,
            ->calls->entity.{snippet_field} AS calls_snippets,
            ->belongs_to->entity.name AS parent_names,
            ->belongs_to->entity.{snippet_field} AS parent_snippets,
            <-belongs_to<-entity.name AS child_names,
            <-belongs_to<-entity.{snippet_field} AS child_snippets
        FROM $fused.id;
    ");

    let mut response = db.query(&sql)
        .bind(("q_vec", query_vec))
        .bind(("q_text", query_text.to_string()))
        .await?
        .check()?;

    // The final projection is always the last statement in the multi-statement
    // query, but the absolute index shifts whenever we add/remove LET bindings
    // (e.g., another BM25 field, a reranker pass). Asking the Response for its
    // own length keeps this resilient to future edits â€” a hardcoded `5` was the
    // source of a silent "no results" bug when the SQL grew to six statements
    // and `take(5)` returned the `$fused` intermediate instead of the SELECT.
    let last_index = response.num_statements().saturating_sub(1);
